import math

_FIELDS = {
    "epoch",
    "validation_score",
    "validation_error",
    "learning_score",
    "learning_error",
}


def _parse_line(line):
    pieces = line.split(";")
    values = {}
    for piece in pieces:
        if "=" not in piece:
            return None
        key, value = piece.split("=", 1)
        key = key.strip()
        if key in values:
            return None
        values[key] = value.strip()
    if set(values) != _FIELDS:
        return None
    try:
        epoch = int(values["epoch"])
        if epoch < 0 or str(epoch) != values["epoch"]:
            return None
        metrics = {key: float(values[key]) for key in _FIELDS - {"epoch"}}
    except ValueError:
        return None
    if not all(math.isfinite(value) for value in metrics.values()):
        return None
    metrics["epoch"] = epoch
    return metrics


def extract_epoch_series(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    sections = [[]]
    for line in text.splitlines():
        if line.strip().startswith("::"):
            sections.append([])
        else:
            sections[-1].append(line)

    result = []
    for lines in sections:
        by_epoch = {}
        for line in lines:
            parsed = _parse_line(line.strip())
            if parsed is not None and parsed["epoch"] not in by_epoch:
                by_epoch[parsed["epoch"]] = parsed
        if not by_epoch:
            continue
        ordered = [by_epoch[epoch] for epoch in sorted(by_epoch)]
        result.append({
            "epochs": [row["epoch"] for row in ordered],
            "validation_score": [row["validation_score"] for row in ordered],
            "validation_error": [row["validation_error"] for row in ordered],
            "learning_score": [row["learning_score"] for row in ordered],
            "learning_error": [row["learning_error"] for row in ordered],
        })
    return result

